  const base = selected ? { id:selected.id, code:selected.code, type:selected.type, serverId:selected.server_id, coin:selected.coin, gold:selected.gold, yen:selected.yen, startsAt:giftDateLocal(selected.starts_at), expiresAt:giftDateLocal(selected.expires_at), maxRedemptions:selected.max_redemptions || "", disabled:Number(selected.disabled) ? "1" : "0" } : { id:"", code:"", type:"1", serverId:"1", coin:"0", gold:"0", yen:"0", startsAt:"", expiresAt:"", maxRedemptions:"", disabled:"0" };
